// AI-Personalized Pricing Module
// Dynamically adjusts pricing per visitor based on real-time signals
// No competing SaaS offers this level of granularity

const pricingCache = new Map();
const DEFAULT_PRICE = 49.99;

function getVisitorPrice(visitorId, sessionData) {
  if (pricingCache.has(visitorId)) {
    return pricingCache.get(visitorId);
  }
  let price = DEFAULT_PRICE;
  // Factor: page views (higher engagement = higher willingness)
  if (sessionData.pageViews > 5) price *= 1.1;
  // Factor: time on site (more time = more interest)
  if (sessionData.sessionDuration > 120) price *= 1.05;
  // Factor: referral source (organic search = higher intent)
  if (sessionData.referrer && sessionData.referrer.includes('google')) price *= 1.15;
  // Factor: device type (mobile users more price sensitive)
  if (sessionData.device === 'mobile') price *= 0.9;
  // Clamp to reasonable range
  price = Math.round(Math.min(Math.max(price, 19.99), 199.99) * 100) / 100;
  pricingCache.set(visitorId, price);
  return price;
}

function clearCache() {
  pricingCache.clear();
}

module.exports = { getVisitorPrice, clearCache };
